export type StoryPalette = "gold" | "dawn" | "sea" | "ember" | "azure" | "forest" | "rose";
export type ArtVariant = "saint" | "sword" | "lamp" | "rosary" | "birds" | "rose";

export type Story = {
  id: string;
  title: string;
  saint: string;
  blurb: string;
  minutes: number;
  age: number;
  publishedAt: string;
  palette: StoryPalette;
  art: ArtVariant;
  hero?: number;
  imageSmall?: number;
  /** Extra tile variants shown in the Gallery alongside hero/tile. */
  extraImages?: number[];
  source: string;
  pages: string[];
};

/**
 * Full text of a page. The last page closes with an invocation,
 * e.g. "St Angela Merici, pray for us."
 */
export function storyPageText(story: Story, page: number): string {
  const text = story.pages[page];
  if (page === story.pages.length - 1) return `${text} ${story.saint}, pray for us.`;
  return text;
}

/** Sort key for saint names, ignoring title prefixes like St, Bl or Blessed. */
export function saintSortKey(saint: string): string {
  return saint.replace(/^(Sts?|Bl|Blessed|Pope|Saint)\.?\s+/i, "");
}

